"""
Helpers to be used directly from a project's ``setup.py``.

Typical usage::

    import setuptools
    from setuptools_us4us import setup_version

    version = setup_version("us4r_vandv")

    setuptools.setup(
        name="us4r_vandv",
        version=version,
        ...
    )
"""
import os
import re
from typing import Optional

from setuptools_us4us.versioning import VersioningError, get_version

VERSION_FILE_TEMPLATE = '''\
# This file is generated by setuptools-us4us, DO NOT EDIT.
__version__ = "{version}"


def is_dev() -> bool:
    """
    Returns true if this version is a development (non-release) build.
    """
    return {is_dev}


def is_stable() -> bool:
    """
    Returns true if this version is a stable (release) build.
    """
    return not is_dev()
'''


def is_dev_version(version: str) -> bool:
    """
    Returns true when the given PEP 440 version is a development version,
    i.e. it carries a ``.devN`` segment and/or a local version label.
    """
    return ".dev" in version or "+" in version


def write_version_file(path: str, version: str) -> None:
    """
    Writes the ``version.py`` file with the given version number.

    :param path: path of the file to write, e.g. ``us4r_vandv/version.py``
    :param version: version number to write
    """
    directory = os.path.dirname(path)
    if directory:
        os.makedirs(directory, exist_ok=True)
    with open(path, "w") as f:
        f.write(VERSION_FILE_TEMPLATE.format(
            version=version,
            is_dev=is_dev_version(version),
        ))


def read_version_file(path: str) -> Optional[str]:
    """
    Reads the ``__version__`` value from the given ``version.py`` file.
    Returns ``None`` when the file does not exist or has no ``__version__``.
    """
    if not os.path.exists(path):
        return None
    with open(path) as f:
        match = re.search(r'^__version__\s*=\s*["\'](.+)["\']\s*$',
                          f.read(), re.MULTILINE)
    return match.group(1) if match is not None else None


def setup_version(package_name: str, root: str = ".") -> str:
    """
    Determines the package version from git, writes it to
    ``<root>/<package_name>/version.py`` and returns it.

    When the version cannot be determined from git (e.g. the package is built
    from an sdist, outside of a git repository), the version already present in
    ``version.py`` is used instead; the file is then left untouched.

    :param package_name: name of the Python package (directory) that holds
      the ``version.py`` file, e.g. ``us4r_vandv``
    :param root: project root directory
    :return: the version number
    :raises VersioningError: when the version can be determined neither from
      git nor from an existing ``version.py``
    """
    version_file = os.path.join(root, package_name, "version.py")
    try:
        version = get_version(cwd=root)
    except (VersioningError, RuntimeError, OSError) as e:
        fallback = read_version_file(version_file)
        if fallback is None:
            raise VersioningError(
                f"Could not determine the version of '{package_name}' from "
                f"git ({e}), and there is no usable '{version_file}'.")
        return fallback
    write_version_file(version_file, version)
    return version
